-- What an invitation request does: one invitee named by first and/or last
-- name, one line, and not already invited and waiting.
create or replace function public.setup_invitation_plan(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_first text := btrim(coalesce(p_args->>'first_name', ''));
  v_last text := btrim(coalesce(p_args->>'last_name', ''));
begin
  if length(v_first) > 120 or length(v_last) > 120 or (v_first || v_last) ~ '[\r\n]' then
    raise exception 'a name is one line of at most 120 characters' using errcode = '22023';
  end if;
  if v_first = '' and v_last = '' then
    raise exception 'an invitation names a person: give a first or a last name' using errcode = '22023';
  end if;
  if exists (select 1 from public.invitations i
              where i.workspace_id = p_workspace_id and i.redeemed_at is null and not i.is_admin
                and lower(i.invited_first_name) = lower(v_first) and lower(i.invited_last_name) = lower(v_last)) then
    raise exception 'an invitation for this person is already open' using errcode = '22023';
  end if;
  return jsonb_build_object(
    'first_name', v_first, 'last_name', v_last,
    'changes', jsonb_build_array(jsonb_build_object('field', 'invitee', 'from', null,
                                                    'to', btrim(v_first || ' ' || v_last))),
    'revision', md5((select count(*) from public.invitations i
                      where i.workspace_id = p_workspace_id and i.redeemed_at is null)::text));
end;
$fn$;
revoke execute on function public.setup_invitation_plan(uuid, jsonb) from public, anon, authenticated;

create or replace function public.mcp_target_create_invitations(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v jsonb;
begin
  perform public.mcp_setup_target_guard(p_workspace_id, p_args, array['workspace_id', 'request_id',
    'first_name', 'last_name']);
  v := public.setup_invitation_plan(p_workspace_id, p_args);
  return jsonb_build_object('kind', 'invitation', 'changes', v->'changes', 'revision', v->>'revision');
end;
$fn$;
revoke execute on function public.mcp_target_create_invitations(uuid, jsonb) from public, anon, authenticated;

-- Runs only after the person confirmed the invitee, through the invite
-- step's own command, which asks manageMembers (or admin) for the person
-- again; this definer asks it first, as add_closure_days does. The answer
-- carries the invitation's id and its status, never the code.
create or replace function public.mcp_op_create_invitations(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_refusal jsonb := public.mcp_setup_refusal(c.workspace_id, p_args, array['workspace_id', 'request_id',
    'first_name', 'last_name']);
  v jsonb;
  v_code text;
  v_id uuid;
begin
  if v_refusal is not null then return v_refusal; end if;
  if not public.has_permission(c.workspace_id, 'manageMembers') then
    return public.mcp_outcome('denied', null, 'forbidden');
  end if;
  v := public.setup_invitation_plan(c.workspace_id, p_args);
  v_code := public.create_invitation(c.workspace_id, false, v->>'first_name', v->>'last_name', null, false);
  select i.id into v_id from public.invitations i where i.workspace_id = c.workspace_id and i.code = v_code;
  return public.mcp_outcome('completed', jsonb_build_object('invitation_id', v_id, 'status', 'open'));
end;
$fn$;
revoke execute on function public.mcp_op_create_invitations(public.mcp_call_context, jsonb) from public, anon, authenticated;

notify pgrst, 'reload schema';

select public.set_deskilo_schema_version(623);
